function oldStyle(value: number, callback: (error: Error | null, result?: number) => void): void {
    setTimeout(() => {
        if (value < 0) callback(new Error("Manfiy son"))
        else callback(null, value * 2)
    }, 10)
}

function promisified(value: number): Promise<number> {
    return new Promise((resolve, reject) => {
        oldStyle(value, (error, result) => {
            if (error) reject(error)
            else resolve(result!)
        })
    })
}

async function main() {
    console.log("Callback natijasi kutilmoqda...")
    const result = await promisified(21)
    console.log("Promise natijasi:", result)

    try {
        await promisified(-1)
    } catch (e) {
        console.log("Xato ushlandi:", (e as Error).message)
    }
}
main()

