function wait(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms))
}

function checkAge(age: number): Promise<string> {
    return new Promise((resolve, reject) => {
        if (age >= 18) resolve("Ruxsat berildi")
        else reject(new Error("Yosh yetarli emas"))
    })
}

wait(50)
    .then(() => checkAge(20))
    .then(result => console.log(result))
    .then(() => checkAge(15))
    .then(result => console.log(result))   // bajarilmaydi
    .catch((error: Error) => console.log("Xato:", error.message))
    .finally(() => console.log("Tekshiruv yakunlandi"))

function delay<T>(ms: number, value: T): Promise<T> {
    return new Promise(resolve => setTimeout(() => resolve(value), ms))
}

function failAfter(ms: number, message: string): Promise<never> {
    return new Promise((_, reject) => setTimeout(() => reject(new Error(message)), ms))
}

async function main() {
    console.log(await delay(10, "muvaffaqiyat"))

    try {
        await failAfter(10, "rad etildi")
    } catch (e) {
        console.log("Xato:", (e as Error).message)
    }

    const pending = delay(1000, "hali tayyor emas")
    console.log("Promise tipi:", typeof pending, "| instanceof Promise:", pending instanceof Promise)
}
main()

