const delay = (ms: number, label: string) =>
    new Promise<string>(resolve => setTimeout(() => resolve(label), ms))

async function sequential(): Promise<string[]> {
    const a = await delay(30, "A")
    const b = await delay(30, "B")
    const c = await delay(30, "C")
    return [a, b, c]
}

async function parallel(): Promise<string[]> {
    return Promise.all([delay(30, "A"), delay(30, "B"), delay(30, "C")])
}

async function main() {
    const t1 = Date.now()
    console.log("Ketma-ket:", await sequential(), `~${Math.round((Date.now() - t1) / 30) * 30}ms`)

    const t2 = Date.now()
    console.log("Parallel:", await parallel(), `~${Math.round((Date.now() - t2) / 30) * 30}ms`)
}
main()

async function riskyOperation(shouldFail: boolean): Promise<string> {
    if (shouldFail) throw new Error("Operatsiya muvaffaqiyatsiz")
    return "Hammasi joyida"
}

async function withTryCatch(): Promise<void> {
    try {
        console.log(await riskyOperation(false))
        console.log(await riskyOperation(true))
    } catch (e) {
        console.log("try/catch:", (e as Error).message)
    } finally {
        console.log("finally har doim ishlaydi")
    }
}

async function withCatchMethod(): Promise<void> {
    const result = await riskyOperation(true).catch(e => `catch metodi: ${(e as Error).message}`)
    console.log(result)
}

async function main() {
    await withTryCatch()
    await withCatchMethod()
}
main()

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms))

async function processItem(item: string): Promise<string> {
    await delay(10)
    return item.toUpperCase()
}

async function main() {
    const items = ["a", "b", "c"]

    // Ketma-ket — har biri oldingisini kutadi
    const sequential: string[] = []
    for (const item of items) {
        sequential.push(await processItem(item))
    }
    console.log("Ketma-ket:", sequential)

    // Parallel — hammasi birga
    const parallel = await Promise.all(items.map(processItem))
    console.log("Parallel:", parallel)

    // Diqqat: forEach bilan await ishlamaydi!
    const wrong: string[] = []
    items.forEach(async item => {
        wrong.push(await processItem(item))
    })
    console.log("forEach bilan (bo'sh):", wrong)
}
main()

