class ApiClient {
    private cache = new Map<string, unknown>()

    private async request<T>(endpoint: string, value: T): Promise<T> {
        await new Promise(resolve => setTimeout(resolve, 5))
        return value
    }

    async get<T>(endpoint: string, fallback: T): Promise<T> {
        if (this.cache.has(endpoint)) {
            console.log(`(keshdan) ${endpoint}`)
            return this.cache.get(endpoint) as T
        }
        const data = await this.request(endpoint, fallback)
        this.cache.set(endpoint, data)
        console.log(`(serverdan) ${endpoint}`)
        return data
    }
}

