function parseAs<T>(json: unknown, shape: Shape): T {
    if (typeof json !== "object" || json === null) throw new TypeError("obyekt kutilgan")
    for (const [k, t] of Object.entries(shape)) if (typeof (json as Record<string, unknown>)[k] !== t) throw new TypeError(`${k}: ${t} kutilgan`)
    return json as T
}
type User = { id: number; name: string; active: boolean }
const shape: Shape = { id: "number", name: "string", active: "boolean" }
const good = parseAs<User>(await Response.json({ id: 1, name: "Ali", active: true }).json(), shape)
console.log(good.name)
try { parseAs<User>(await Response.json({ id: "1", name: "Ali", active: true }).json(), shape) } catch (e) { console.log((e as Error).message) }
